  public getCentroid(zip: string): IZipCentroidRecord | undefined {
    return this.centroids.get(zip);
  }

  public computeHaversineDistance(zip1: string, zip2: string): number {
    const c1 = this.getCentroid(zip1);
    const c2 = this.getCentroid(zip2);
    if (!c1 || !c2) return 250.0;
    const R = 3958.8;
    const dLat = (c2.latitude - c1.latitude) * Math.PI / 180;
    const dLon = (c2.longitude - c1.longitude) * Math.PI / 180;
    const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) + Math.cos(c1.latitude * Math.PI / 180) * Math.cos(c2.latitude * Math.PI / 180) * Math.sin(dLon / 2) * Math.sin(dLon / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return +(R * c).toFixed(1);
  }
